script:
# Check if a draft note already exists for this file
if doc.file:
    existing_draft = frappe.db.exists(
        "Correspond Noting",
        {
            "file": doc.file,
            "docstatus": 0,
            "name": ["!=", doc.name or ""]
        }
    )
    if existing_draft:
        frappe.throw("Action Blocked: A note is currently in the Draft stage for this file. You cannot create a new note until the existing draft is submitted.")
